from retry_queue import RetryQueue

def test_notifies_on_final_failure():
    q = RetryQueue(max_retries=1)
    q.jobs["j1"] = {"attempts": 0, "status": "pending"}
    q.record_failure("j1")  # attempts becomes 1 == max_retries, should notify
    assert q.jobs["j1"]["status"] == "failed_permanently"
